export function createPassArchive(files, now) {
  if (!Array.isArray(files) || files.length < 4 || files.length > 15 || !Number.isSafeInteger(now)) fail();
  const date = new Date(now), year = date.getUTCFullYear();
  if (year < 1980 || year > 2107) fail();
  const dosDate = (year - 1980) << 9 | (date.getUTCMonth() + 1) << 5 | date.getUTCDate();
  const dosTime = date.getUTCHours() << 11 | date.getUTCMinutes() << 5 | Math.floor(date.getUTCSeconds() / 2);
  const local = [], central = [], names = new Set(); let offset = 0;
  for (const file of files) {
    if (!file || !/^(?:pass\.json|manifest\.json|signature|(?:icon|background|artwork|strip|logo|primaryLogo)(?:@2x|@3x)?\.png)$/u.test(file.name ?? '') || names.has(file.name)
      || !(file.data instanceof Uint8Array) || !file.data.length || file.data.length > 256 * 1024) fail();
    names.add(file.name); const name = Buffer.from(file.name), data = Buffer.from(file.data), crc = crc32(data);
    const header = Buffer.alloc(30 + name.length); header.writeUInt32LE(0x04034b50); header.writeUInt16LE(20, 4); header.writeUInt16LE(0x0800, 6);
    header.writeUInt16LE(dosTime, 10); header.writeUInt16LE(dosDate, 12); header.writeUInt32LE(crc, 14); header.writeUInt32LE(data.length, 18); header.writeUInt32LE(data.length, 22); header.writeUInt16LE(name.length, 26); name.copy(header, 30);
    const directory = Buffer.alloc(46 + name.length); directory.writeUInt32LE(0x02014b50); directory.writeUInt16LE(0x0314, 4); directory.writeUInt16LE(20, 6); directory.writeUInt16LE(0x0800, 8);
    directory.writeUInt16LE(dosTime, 12); directory.writeUInt16LE(dosDate, 14); directory.writeUInt32LE(crc, 16); directory.writeUInt32LE(data.length, 20); directory.writeUInt32LE(data.length, 24); directory.writeUInt16LE(name.length, 28); directory.writeUInt32LE(0o100644 * 65536, 38); directory.writeUInt32LE(offset, 42); name.copy(directory, 46);
    local.push(header, data); central.push(directory); offset += header.length + data.length;
  }
  const directory = Buffer.concat(central), end = Buffer.alloc(22); end.writeUInt32LE(0x06054b50); end.writeUInt16LE(files.length, 8); end.writeUInt16LE(files.length, 10); end.writeUInt32LE(directory.length, 12); end.writeUInt32LE(offset, 16);
  const archive = Buffer.concat([...local, directory, end]); if (archive.length > 1024 * 1024) fail(); return archive;
}

export function buildAppleWalletPass({ identity, attendee, organizationName, verificationUrl, now = Date.now() } = {}) {
  const event = attendee?.event, walletIdentity=WALLET_IDENTITIES.find(item=>item.value===attendee?.walletIdentity);
  const richCard = attendee?.walletRequested === true && Boolean(walletIdentity);
  const siteIdentity = walletIdentity ? cardCommunityFields(attendee?.cardCommunity) : null;
  const profile = richCard ? cardProfileFields(attendee.cardProfile) : null;
  const community = cardCommunityLabel(siteIdentity);
  const communityFields = community ? [{ key: 'ggj-community', label: 'GGJ 社群', value: community }] : [];
  if ((attendee?.walletRequested === true || attendee?.walletIdentity !== undefined) && !walletIdentity) fail('WALLET_PASS_INPUT_INVALID');
  if (!identity?.privateKey || attendee?.admissionStatus !== 'confirmed' || !/^[A-Za-z0-9_-]{43}$/u.test(attendee.registrationId ?? '')
    || attendee.referenceCode !== attendee.registrationId
    || !line(attendee.name, 160) || !line(organizationName, 80) || !line(event?.id, 80) || !line(event?.title, 300)
    || !/^\d{4}-\d{2}-\d{2}$/u.test(event?.date ?? '') || !line(event?.time, 100) || !line(event?.venue, 500)
    || !['Asia/Shanghai', 'Asia/Taipei', 'Asia/Hong_Kong'].includes(event?.timezone)) fail('WALLET_PASS_INPUT_INVALID');
  if (!richCard) {
    if (!line(verificationUrl, 2048)) fail('WALLET_PASS_INPUT_INVALID');
    let url;
    try { url = new URL(verificationUrl); } catch { fail('WALLET_PASS_INPUT_INVALID'); }
    const legacyVerification = ['/api/registration/wallet/verify/', '/api/admin/registration/wallet/verify/'].some(prefix => url.pathname.startsWith(prefix)) && !url.hash;
    const staffEntry = url.pathname === '/admin/checkin/' && /^#ticket=[A-Za-z0-9_-]{22}$/u.test(url.hash);
    if (url.origin !== 'https://api.artdico.host' || !(legacyVerification || staffEntry) || url.search || url.username || url.password) fail('WALLET_PASS_INPUT_INVALID');
  }
  const start = /^([01]\d|2[0-3]):[0-5]\d/u.exec(event.time)?.[0]; if (!start) fail('WALLET_PASS_INPUT_INVALID');
  const relevantDate = event.date + 'T' + start + ':00+08:00';
  if (!Number.isFinite(Date.parse(relevantDate)) || new Date(Date.parse(event.date + 'T00:00:00Z')).toISOString().slice(0, 10) !== event.date) fail('WALLET_PASS_INPUT_INVALID');
  const meetupCard = richCard && event.id === eventConfig.id;
  const faceName = { key: 'name', value: attendee.name, semantics: { attendeeName: attendee.name } };
  const person = { ...faceName, label: meetupCard ? '姓名' : '参会人' };
  const title = { key: 'event', label: '活动', value: event.title };
  const date = { key: 'date', label: '日期', value: event.date };
  const time = { key: 'time', label: '时间', value: event.time };
  const venue = { key: 'venue', label: '地点', value: event.venue };
  const cardAffiliations = richCard ? [
    { key: 'ggj-site', label: 'GGJ 站点', value: siteIdentity?.site },
    { key: 'ggj-role', label: '社群角色／分工', value: siteIdentity?.role },
    { key: 'organization', label: '学校／机构', value: profile?.organization },
  ].filter(field => field.value) : [];
  const maxAffiliationLength = cardAffiliations.length > 2 ? 9 : 14;
  const affiliations = cardAffiliations.map(field => {
    const characters = [...field.value];
    return { ...field, key: field.key + '-short', row: 1,
      value: characters.length > maxAffiliationLength ? characters.slice(0, maxAffiliationLength - 1).join('') + '…' : field.value };
  });
  const faceIdentity = walletIdentity ? { key: 'identity', value: walletIdentity.label } : null;
  const identityField = faceIdentity ? { ...faceIdentity, label: meetupCard ? '身份' : richCard ? '卡面身份' : '入场身份' } : null;
  const fullCardDetails = richCard ? [
    { ...person, key: 'details-name' }, { ...identityField, key: 'details-identity' },
    { ...title, key: 'details-event' }, { ...date, key: 'details-date' }, { ...time, key: 'details-time' },
  ] : [];
  const cardTitle = meetupCard ? PUBLIC_MEETUP_TITLE : null;
  const confirmedVenue = meetupCard && event.venue === eventConfig.venue.address;
  const separateVenue = affiliations.length > 0;
  const cardPlace = { ...venue, key: 'venue-short', value: confirmedVenue && separateVenue ? '前海5号楼' : commemorativeCardVenue(event.venue) };
  const activities = meetupCard ? [{ key: 'activities', label: '活动内容', value: '讲座・站点交流・游戏展' }] : [];
  const programFields = meetupCard ? MEETUP_PROGRAM_FIELDS : [];
  const scheduleFields = meetupCard ? MEETUP_SCHEDULE_FIELDS : [];
  const cardGuides = [];
  if (richCard) cardGuides.push(['directions', '场地导航', appleMapsDirectionsUrl(event.venue), '在 Apple 地图中查看路线']);
  if (meetupCard) cardGuides.push(['agenda', '讲座日程', PUBLIC_AGENDA_URL, '查看最新讲座与活动日程'],
    ['showcase', '参展游戏', PUBLIC_SHOWCASE_URL, '浏览已公布的游戏与作品'],
    ['huodongxing', '活动行', PUBLIC_REGISTRATION_URL, '打开活动行活动页']);
  const guideFields = cardGuides.map(([key, label, value, linkText]) => ({ key, label, value,
    attributedValue: '<a href="' + value + '">' + linkText + '</a>' }));
  const backFields = [...(cardTitle ? [{ key: 'co-brand-title', label: '联名活动', value: cardTitle }] : []),
    venue, ...guideFields, ...cardAffiliations, ...programFields, ...scheduleFields, ...fullCardDetails,
    ...(profile?.phone ? [{ key: 'phone', label: '电话', value: profile.phone, dataDetectorTypes: ['PKDataDetectorTypePhoneNumber'] }] : []),
    ...(meetupCard ? [{ key: 'event-details', label: '活动详情', value: PUBLIC_EVENT_DETAILS_URL,
      attributedValue: '<a href="' + PUBLIC_EVENT_DETAILS_URL + '">查看活动详情</a>' }] : []),
    ...(!richCard ? [{ key: 'reference', label: '报名编号', value: attendee.referenceCode }, ...communityFields] : []),
    { key: 'notice', label: '说明', value: richCard ? '本卡用于纪念收藏。现场签到请使用活动行原电子票。' : '此凭证仅表示参会名额。讲者、展位及住宿另行确认；请以在线核对结果为准。' }];
  const posterGeneric = meetupCard ? {
    primaryFields: [{ ...faceIdentity, key: 'poster-identity' }, { ...faceName, key: 'poster-name' },
      ...affiliations.slice(0, 2).map(({ key, label, value }) => ({ key: 'poster-' + key, label, value }))],
    footerFields: [{
      key: 'poster-event-summary', label: '活动时间与地点 · UTC+8',
      value: [event.date, event.time, confirmedVenue ? '前海5号楼' : cardPlace.value].join(' · '),
    }],
    additionalInfoFields: [...programFields, date, { ...time, label: '时间 · UTC+8' }, venue, ...scheduleFields, ...cardAffiliations]
      .map(field => ({ ...field, key: 'poster-info-' + field.key })),
    backFields: backFields.map(field => ({ ...field, key: 'poster-details-' + field.key })),
  } : null;
  const pass = { formatVersion: 1, passTypeIdentifier: identity.passTypeIdentifier, serialNumber: event.id + '-' + attendee.registrationId,
    teamIdentifier: identity.teamId, organizationName, description: (cardTitle ?? event.title) + (richCard ? ' 电子纪念卡' : '参会凭证'),
    ...(!meetupCard ? { logoText: organizationName } : {}),
    foregroundColor: 'rgb(255,255,255)', backgroundColor: 'rgb(18,18,18)', labelColor: 'rgb(238,238,238)', sharingProhibited: true,
    ...(!richCard ? { relevantDate, expirationDate: event.date + 'T23:59:59+08:00',
      barcodes: [{ format: 'PKBarcodeFormatQR', message: verificationUrl, messageEncoding: 'iso-8859-1' }] } : {}),
    ...(!meetupCard ? { preferredStyleSchemes: richCard ? ['eventTicket'] : ['posterEventTicket', 'eventTicket'] } : {}),
    ...(posterGeneric ? { posterGeneric } : {}),
    semantics: { eventName: event.title, eventStartDate: relevantDate, eventType: 'PKEventTypeGeneric',
      venueName: confirmedVenue ? eventConfig.venue.name : event.venue,
      ...(confirmedVenue ? { venueRegionName: eventConfig.venue.city } : {}),
      ...(walletIdentity ? { attendeeName: attendee.name, ...(!richCard ? { admissionLevel: walletIdentity.label } : {}) } : {}) },
    eventTicket: {
      ...(richCard ? {
        ...(separateVenue ? { headerFields: [cardPlace] } : {}),
        secondaryFields: meetupCard ? [faceIdentity, faceName] : [person, identityField],
        auxiliaryFields: [date, { ...time, label: meetupCard ? '时间 · UTC+8' : time.label }, ...activities, ...affiliations,
          ...(separateVenue ? [] : [{ ...cardPlace, row: 1 }])],
      } : {
        headerFields: [identityField ?? { key: 'status', label: '参会名额', value: '已确认' }],
        primaryFields: [title],
        secondaryFields: [{ ...person, label: '参加人' }],
        auxiliaryFields: [date, time],
        ...(communityFields.length ? { additionalInfoFields: communityFields } : {}),
      }),
      backFields,
    } };
  const artwork = richCard ? [...(meetupCard ? [...KEEPSAKE_TITLE_LOGOS, ...KEEPSAKE_POSTER_IMAGES] : []), ...KEEPSAKE_STRIPS] : [
    { name: 'background.png', data: BRAND_IMAGES.background }, { name: 'background@2x.png', data: BRAND_IMAGES.background },
    { name: 'artwork.png', data: BRAND_IMAGES.artwork }, { name: 'artwork@2x.png', data: BRAND_IMAGES.artwork },
  ];
  const files = [{ name: 'pass.json', data: Buffer.from(JSON.stringify(pass)) },
    { name: 'icon.png', data: BRAND_IMAGES.icon }, { name: 'icon@2x.png', data: BRAND_IMAGES.icon2 }, ...artwork];
  const manifest = Buffer.from(JSON.stringify(Object.fromEntries(files.map(file => [file.name, createHash('sha1').update(file.data).digest('hex')]))));
  files.push({ name: 'manifest.json', data: manifest }, { name: 'signature', data: signManifest({ manifest, ...identity, now }) });
  return createPassArchive(files, now);
}
